# Plan escena por escena (escenas 16 a 183 del guion visual v4 de Visuales).
# base: lista de planos que se reparten la escena: ("i", imagen, opciones) / ("v", clip, inicio) / ("f", fondo)
#       "sigue" = continúa el plano anterior.
# g:    gráficos encima; "at" = palabra de la voz que los dispara (o segundos desde el inicio de la escena).

def i(img, pos="50% 50%", mov=None, **k): return ("i", img, dict(pos=pos, mov=mov, **k))
def v(clip, ms=1.0, **k): return ("v", clip, dict(ms=ms, **k))
def f(kind="noche", **k): return ("f", kind, k)

